手机小说大全 m.xiaoshuodaquan.com

, 更多电子书下载 shushu.com.cn

请输出严格符合以下结构的 JSON：

{
  "chapter_title": "577 巫部之宴_690 冲击化神！",
  "chapter_outline": ["细纲要点1", "细纲要点2", "细纲要点3"],
  "truth_base": {
    "protagonist_plan": "主角动机与算盘",
    "antagonist_horizon": "配角视界与误判",
    "information_gap": "核心信息差",
    "deadline": "迫在眉睫的死线"
  },
  "segments": {
    "opening": {
      "anchor_start": "破题第一句",
      "anchor_end": "破题定势末句",
      "text": "破题正文（约150~250字）"
    },
    "ramp_up": {
      "anchor_start": "接破题末句的下一句",
      "anchor_end": "高潮爆发首句(必须与climax.anchor_start完全一致)",
      "text": "蓄水铺垫正文（约600~800字，末尾包含climax.anchor_start）"
    },
    "climax": {
      "core_conflict": "核心冲突与反杀形式",
      "anchor_start": "高潮爆发第一句",
      "anchor_end": "高潮定调末句",
      "text": "高潮正文（约600~800字）"
    },
    "aftershock": {
      "anchor_start": "接高潮末句的下一句",
      "anchor_end": "断章引爆句(必须与cliffhanger.anchor_start完全一致)",
      "text": "余波转折正文（约400~500字，末尾包含cliffhanger.anchor_start）"
    },
    "cliffhanger": {
      "anchor_start": "断章危机引爆句",
      "anchor_end": "全章最后一句话",
      "text": "断章正文（约150~250字）"
    }
  }
}

墨绿衫年男子脸色一变，神识一扫整个劫云范围内，最后视线落在深渊奇兽乒，难以置信，“难道有人在深渊奇兽的体龘内，冲击化神？”
